// jasql-eval runs the golden-query evaluation from the command line so CI and
// operators can track accuracy without an MCP client.
//
// Usage:
//
//	go run ./cmd/jasql-eval -data ./data/kcb [-golden path] [-top-k 5] [-verbose]
package main

import (
	"context"
	"encoding/json"
	"flag"
	"fmt"
	"log"
	"os"
	"path/filepath"

	"jasql/internal/catalog"
	"jasql/internal/oracle"
)

func main() {
	var (
		dataDir    string
		goldenPath string
		topK       int
		verbose    bool
		profile    string
	)
	flag.StringVar(&dataDir, "data", filepath.Join("data", "kcb"), "Path to metadata directory")
	flag.StringVar(&goldenPath, "golden", "", "Path to golden_queries.json (default <data>/golden_queries.json)")
	flag.IntVar(&topK, "top-k", 5, "Search depth for table-selection accuracy")
	flag.BoolVar(&verbose, "verbose", false, "Print per-case results including misses")
	flag.StringVar(&profile, "profile", "", "DB profile id for execution-based checks (requires -tags oracle build)")
	flag.Parse()

	cat, err := catalog.Load(dataDir)
	if err != nil {
		log.Fatalf("load catalog: %v", err)
	}
	var counter catalog.RowCounter
	if profile != "" {
		mgr := oracle.NewManager(dataDir)
		defer mgr.Close()
		counter = func(ctx context.Context, sql string) (int64, error) {
			return mgr.CountRows(ctx, profile, sql)
		}
	}
	res, err := cat.RunEvaluationExec(context.Background(), goldenPath, topK, counter)
	if err != nil {
		log.Fatalf("run evaluation: %v", err)
	}
	results := res["results"].([]catalog.EvalCaseResult)
	summary := map[string]any{}
	for k, v := range res {
		if k != "results" {
			summary[k] = v
		}
	}
	b, _ := json.MarshalIndent(summary, "", "  ")
	fmt.Println(string(b))
	if verbose {
		for _, r := range results {
			status := "ok"
			if !r.TableHit || !r.JoinPathOK || !r.MetricHit {
				status = "MISS"
			}
			fmt.Printf("[%s] table_hit=%t rank=%d col_recall=%.2f join=%t %.70s\n",
				status, r.TableHit, r.TableRank, r.ColumnRecall, r.JoinPathOK, r.Question)
			for _, m := range r.Missing {
				fmt.Printf("       missing: %s\n", m)
			}
		}
	}
	if acc, ok := summary["table_selection_acc"].(float64); ok && acc < 0.7 {
		fmt.Fprintln(os.Stderr, "table_selection_acc below 0.7")
		os.Exit(1)
	}
}
package catalog

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"
)

// GoldenQuery is one entry of the CI-runnable evaluation set
// (data/<set>/golden_queries.json).
type GoldenQuery struct {
	ID              any      `json:"id,omitempty"`
	Question        string   `json:"question"`
	ExpectedTables  []string `json:"expected_tables"`
	ExpectedColumns []string `json:"expected_columns,omitempty"` // "TABLE.COLUMN" or bare column
	ExpectedMetrics []string `json:"expected_metrics,omitempty"`
	ExpectedSQL     string   `json:"expected_sql,omitempty"`
	// row-count sanity bounds for execution-based evaluation (optional; both
	// unset = only "executes without error" is checked)
	ExpectedMinRows *int64 `json:"expected_min_rows,omitempty"`
	ExpectedMaxRows *int64 `json:"expected_max_rows,omitempty"`
	Note            string `json:"note,omitempty"`
}

// RowCounter executes SELECT COUNT(*) over a golden SQL against a real
// database. Injected (e.g. oracle.Manager.CountRows) so the catalog package
// stays DB-free; nil disables execution-based evaluation.
type RowCounter func(ctx context.Context, sql string) (int64, error)

type EvalCaseResult struct {
	Question       string   `json:"question"`
	TableHit       bool     `json:"table_hit"`
	TableRank      int      `json:"table_rank,omitempty"` // 1-based rank of first expected table
	ColumnRecall   float64  `json:"column_recall"`
	MetricHit      bool     `json:"metric_hit"`
	JoinPathOK     bool     `json:"join_path_ok"`
	ExpectedSQLOK  *bool    `json:"expected_sql_valid,omitempty"`
	ExecutedRows   *int64   `json:"executed_rows,omitempty"`
	RowSanityOK    *bool    `json:"row_sanity_ok,omitempty"`
	ExecError      string   `json:"exec_error,omitempty"`
	Missing        []string `json:"missing,omitempty"`
	DurationMillis int64    `json:"duration_ms"`
}

// RunEvaluation scores search/metric/join accuracy against the golden set.
// It is deterministic and DB-free, so it runs in CI via `go test ./...` or
// through the run_evaluation MCP tool.
func (c *Catalog) RunEvaluation(goldenPath string, topK int) (map[string]any, error) {
	return c.RunEvaluationExec(context.Background(), goldenPath, topK, nil)
}

// RunEvaluationExec additionally executes each expected_sql through the
// injected RowCounter for execution success rate and row-count sanity
// (expected_min_rows / expected_max_rows bounds).
func (c *Catalog) RunEvaluationExec(ctx context.Context, goldenPath string, topK int, counter RowCounter) (map[string]any, error) {
	if goldenPath == "" {
		goldenPath = filepath.Join(c.DataDir, "golden_queries.json")
	}
	if topK <= 0 {
		topK = 5
	}
	var golden []GoldenQuery
	if err := readJSON(goldenPath, &golden); err != nil {
		return nil, err
	}
	results := make([]EvalCaseResult, 0, len(golden))
	tableHits, metricHits, joinOK, sqlValid, sqlTotal := 0, 0, 0, 0, 0
	execTotal, execSuccess, sanityTotal, sanityOK := 0, 0, 0, 0
	colRecallSum := 0.0
	var totalDur time.Duration
	for _, g := range golden {
		start := time.Now()
		r := EvalCaseResult{Question: g.Question, JoinPathOK: true, MetricHit: true}
		search := c.SearchSchema(SearchRequest{Question: g.Question, TopK: topK, IncludeColumns: true, MaxColumns: 12})
		rankOf := func(want string) int {
			t, ok := c.ResolveTable(want)
			if !ok {
				return 0
			}
			for i, res := range search.Results {
				if res.Table == t.FQN {
					return i + 1
				}
			}
			return 0
		}
		for _, want := range g.ExpectedTables {
			if rank := rankOf(want); rank > 0 {
				r.TableHit = true
				if r.TableRank == 0 || rank < r.TableRank {
					r.TableRank = rank
				}
			} else {
				r.Missing = append(r.Missing, "table:"+want)
			}
		}
		// column recall over matched columns of the expected tables
		if len(g.ExpectedColumns) > 0 {
			found := 0
			for _, want := range g.ExpectedColumns {
				wantCol := cleanIdent(want)
				if i := strings.LastIndex(wantCol, "."); i >= 0 {
					wantCol = wantCol[i+1:]
				}
				hit := false
				for _, res := range search.Results {
					for _, m := range res.MatchedColumns {
						if m.Name == wantCol {
							hit = true
							break
						}
					}
				}
				if hit {
					found++
				} else {
					r.Missing = append(r.Missing, "column:"+want)
				}
			}
			r.ColumnRecall = round(float64(found) / float64(len(g.ExpectedColumns)))
		} else {
			r.ColumnRecall = 1
		}
		for _, want := range g.ExpectedMetrics {
			if len(c.LookupMetrics(want)) == 0 {
				r.MetricHit = false
				r.Missing = append(r.Missing, "metric:"+want)
			}
		}
		if len(g.ExpectedTables) > 1 {
			out, err := c.GetJoinPaths(JoinPathRequest{Tables: g.ExpectedTables})
			if err != nil {
				r.JoinPathOK = false
			} else {
				for _, p := range out["join_paths"].([]JoinPathResult) {
					if !p.Found {
						r.JoinPathOK = false
						r.Missing = append(r.Missing, "join:"+p.From+"->"+p.To)
					}
				}
			}
		}
		if strings.TrimSpace(g.ExpectedSQL) != "" {
			sqlTotal++
			v := c.ValidateSQL(ValidateRequest{SQL: g.ExpectedSQL})
			ok := v.Valid
			r.ExpectedSQLOK = &ok
			if ok {
				sqlValid++
			} else {
				for _, e := range v.Errors {
					r.Missing = append(r.Missing, "sql_error:"+e.Message)
				}
			}
			// execution-based check: run against the real DB when a counter
			// is injected and static validation passed
			if counter != nil && ok {
				execTotal++
				n, err := counter(ctx, g.ExpectedSQL)
				if err != nil {
					r.ExecError = err.Error()
					r.Missing = append(r.Missing, "exec:"+truncateEvalStr(err.Error(), 120))
				} else {
					execSuccess++
					r.ExecutedRows = &n
					if g.ExpectedMinRows != nil || g.ExpectedMaxRows != nil {
						sanityTotal++
						sane := (g.ExpectedMinRows == nil || n >= *g.ExpectedMinRows) &&
							(g.ExpectedMaxRows == nil || n <= *g.ExpectedMaxRows)
						r.RowSanityOK = &sane
						if sane {
							sanityOK++
						} else {
							r.Missing = append(r.Missing, fmt.Sprintf("rows:%d (expected %s..%s)", n, i64str(g.ExpectedMinRows), i64str(g.ExpectedMaxRows)))
						}
					}
				}
			}
		}
		dur := time.Since(start)
		r.DurationMillis = dur.Milliseconds()
		totalDur += dur
		if r.TableHit {
			tableHits++
		}
		if r.MetricHit {
			metricHits++
		}
		if r.JoinPathOK {
			joinOK++
		}
		colRecallSum += r.ColumnRecall
		results = append(results, r)
	}
	n := len(golden)
	summary := map[string]any{
		"golden_path":         goldenPath,
		"cases":               n,
		"table_selection_acc": ratio(tableHits, n),
		"column_recall_avg":   round(colRecallSum / float64(max(1, n))),
		"metric_lookup_acc":   ratio(metricHits, n),
		"join_path_acc":       ratio(joinOK, n),
		"expected_sql_valid":  ratio(sqlValid, max(1, sqlTotal)),
		"avg_response_ms":     totalDur.Milliseconds() / int64(max(1, n)),
		"results":             results,
	}
	if counter != nil {
		summary["execution_checked"] = execTotal
		summary["execution_success_rate"] = ratio(execSuccess, max(1, execTotal))
		summary["row_sanity_checked"] = sanityTotal
		summary["row_sanity_rate"] = ratio(sanityOK, max(1, sanityTotal))
	}
	return summary, nil
}

func i64str(v *int64) string {
	if v == nil {
		return "∞"
	}
	return fmt.Sprint(*v)
}

func truncateEvalStr(s string, n int) string {
	if len(s) <= n {
		return s
	}
	return s[:n] + "..."
}

func ratio(a, b int) float64 {
	if b == 0 {
		return 0
	}
	return round(float64(a) / float64(b))
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

// FileExists is a small helper for callers deciding whether an optional
// golden set is present.
func FileExists(path string) bool {
	_, err := os.Stat(path)
	return err == nil
}
# 평가 체계

정확도 개선이 실제로 개선인지 수치로 검증하는 체계입니다. DB 연결 없이
결정적으로 동작하므로 CI에서 매 커밋 실행됩니다.

## 실행 방법 3가지

```sh
go test ./...                    # CI — 골든셋 평가 포함, 임계값 미달 시 실패
go run ./cmd/jasql-eval -verbose # CLI — 케이스별 미스 출력
# MCP: run_evaluation {golden_path?, top_k?}
```

`jasql-eval` 플래그: `-data`(기본 data/kcb), `-golden`(기본
`<data>/golden_queries.json`), `-top-k`(기본 5), `-verbose`.
table_selection_acc < 0.7이면 종료 코드 1 (파이프라인 게이트용).

## 측정 지표

| 지표 | 정의 | 현재 임계값(테스트) |
| --- | --- | --- |
| `table_selection_acc` | 기대 테이블 중 하나라도 검색 top-k에 든 케이스 비율 | ≥ 0.85 |
| `column_recall_avg` | 기대 컬럼이 매칭 컬럼에 나타난 평균 재현율 | ≥ 0.8 |
| `metric_lookup_acc` | 기대 지표가 사전에서 조회되는 비율 | = 1.0 |
| `join_path_acc` | 다중 테이블 케이스에서 모든 쌍의 조인 경로 존재 비율 | ≥ 0.85 |
| `expected_sql_valid` | 기대 SQL이 `validate_sql`을 통과하는 비율 | = 1.0 |
| `avg_response_ms` | 케이스당 평균 처리 시간 | (참고용) |

임계값은 80케이스 실측(table 0.94 / column 0.90 / join 0.94)보다 약간
낮게 잡아 **회귀는 잡고 플레이크는 방지**합니다. 정확도를 크게 올린 뒤에는
임계값도 함께 올려 개선을 고정하십시오 (`internal/catalog/eval_test.go`).

## 골든셋 형식 — `golden_queries.json`

```json
[{"id": 2,
  "question": "2025년 6월 기준 평균 신용점수를 등급별로 보여줘",
  "expected_tables": ["DWSVC.VWISE6L_BS_V20"],
  "expected_columns": ["LST_SCORE", "SCR_GRAD", "BS_YR_MON"],
  "expected_metrics": ["평균 신용점수"],
  "expected_sql": "SELECT ... FETCH FIRST 100 ROWS ONLY",
  "note": "curated"}]
```

- `expected_tables`: 스키마-한정 이름. 2개 이상이면 조인 경로도 평가됨
- `expected_columns`: 베어 컬럼명 또는 `TBL.COL` (베어로 정규화되어 비교)
- `expected_sql`: 있으면 검증기 통과 여부를 측정 — **검증을 통과하는 SQL만**
  넣으세요 (데이터셋 오타가 지표를 오염시키지 않도록)
- `note`: 자동 생성 케이스는 출처(sql_datasets id, 도메인, 난이도)가 기록됨

## 골든셋 확장 — `jasql-goldgen`

`sql_datasets.json`(7,583건)에서 대표 케이스를 자동 선별합니다.

```sh
go run ./cmd/jasql-goldgen -data ./data/kcb -n 80 -keep 5
```

동작:

1. 기존 골든셋 상단 `-keep`개(수작업 케이스)를 보존
2. 후보 필터: 질문·SQL 비어있지 않음, **대상 테이블이 카탈로그에 전부
   실존**, 중복 질문 제외
3. `expected_columns`는 카탈로그 실존 검증 후 채택(최대 6),
   `expected_metrics`는 지표 사전 매칭으로 도출
4. `expected_sql`은 정적 검증을 통과한 경우에만 포함
5. **도메인 × 난이도 버킷 층화** 라운드로빈으로 `-n`까지 선별 (특정 업무
   영역 쏠림 방지, 결정적 순서)

권장 운영: 분기마다 재생성 + 새 업무 질문을 수작업 케이스로 상단에 추가
(`-keep` 값 증가).

## 미스 분석 워크플로

```sh
go run ./cmd/jasql-eval -verbose | grep -A3 MISS
```

| 미스 유형 | 흔한 원인 | 해결 |
| --- | --- | --- |
| `table:...` | 논리명/설명에 질문 어휘 없음 | glossary 동의어 추가, overrides로 테이블 설명 보강 |
| `column:...` | 컬럼 논리명 부재/불일치 | overrides.columns.synonyms |
| `metric:...` | 지표 별칭 누락 | metrics.json aliases 추가 |
| `join:A->B` | 조인 그래프 공백 | `suggest_joins` → preferred_joins 추가 |
| `sql_error:...` | 기대 SQL이 검증 위반 | 기대 SQL 수정 또는 검증 룰 오탐 확인 |

실사례: 80케이스 도입 직후 join 미스가 전부 `TBKP94A`(거래기관 마스터)
엣지 부재였고, preferred_joins 4건 추가로 join_path_acc 0.86 → 0.94.

## CI 통합

`go test ./...`가 곧 게이트입니다. 골든셋 파일이 없으면 해당 테스트는
skip되므로, 파이프라인에서는 데이터 포함 체크아웃을 사용하세요.
평가 소요는 80케이스 기준 약 13초입니다.

## 결과 기반 평가 (실 DB 연결 시)

DB 프로파일을 지정하면 골든셋의 `expected_sql`을 실제로 실행해 두 지표를
추가 측정합니다 (`SELECT COUNT(*)` 래핑 — read-only 가드·타임아웃 적용):

```sh
go run -tags oracle ./cmd/jasql-eval -profile oracle-prod-vip-01
# MCP: run_evaluation {profile: "oracle-prod-vip-01"}
```

| 추가 지표 | 정의 |
| --- | --- |
| `execution_success_rate` | 정적 검증을 통과한 expected_sql이 오류 없이 실행되는 비율 |
| `row_sanity_rate` | 결과 건수가 `expected_min_rows`~`expected_max_rows` 범위인 비율 |

골든 케이스에 범위를 지정하는 법 (둘 다 선택; 없으면 실행 성공만 확인):

```json
{"question": "...", "expected_sql": "...",
 "expected_min_rows": 1, "expected_max_rows": 100000}
```

케이스별 결과에는 `executed_rows`, `row_sanity_ok`, `exec_error`가 담기므로
"문법은 맞는데 0행/폭주"인 의미 오류를 골든셋 수준에서 잡을 수 있습니다.
실행 요건: `-tags oracle` 빌드 + Instant Client
([oracle-connector.md](oracle-connector.md)).

