func TestEvaluationCLI(t *testing.T) {
	binary := filepath.Join(t.TempDir(), "jasql-eval")
	if out, err := exec.Command("go", "build", "-o", binary, ".").CombinedOutput(); err != nil {
		t.Fatalf("build CLI: %v\n%s", err, out)
	}
	for _, tc := range []struct {
		name, extra, status, diagnostic                      string
		tableAcc, columnRecall, metricAcc, joinAcc, sqlValid float64
		exitCode                                             int
	}{
		{"column_only", `"expected_columns":["NONEXISTENT"]`, "MISS", "column:NONEXISTENT", 1, 0, 1, 1, 0, 0},
		{"sql_only", `"expected_columns":["CUST_NO"],"expected_sql":"DELETE FROM TS.TBL1"`, "MISS", "sql_error:", 1, 1, 1, 1, 0, 0},
		{"no_sql", `"expected_columns":["CUST_NO"]`, "ok", "", 1, 1, 1, 1, 0, 0},
		{"no_profile", `"expected_columns":["CUST_NO"],"expected_sql":"SELECT CUST_NO FROM TS.TBL1","expected_min_rows":999`, "ok", "", 1, 1, 1, 1, 1, 0},
		{"table_miss", `"expected_tables":["TS.ABSENT"]`, "MISS", "table:TS.ABSENT", 0, 1, 1, 1, 0, 1},
		{"metric_miss", `"expected_metrics":["ABSENT_METRIC"]`, "MISS", "metric:ABSENT_METRIC", 1, 1, 0, 1, 0, 0},
		{"join_miss", `"expected_tables":["TS.TBL1","TS.TBL2"]`, "MISS", "join:", 1, 1, 1, 0, 0, 0},
	} {
		t.Run(tc.name, func(t *testing.T) {
			dir := t.TempDir()
			question := "TBL1 CUST_NO " + tc.name
			golden := map[string]any{"question": question, "expected_tables": []string{"TS.TBL1"}}
			var extra map[string]any
			if err := json.Unmarshal([]byte("{"+tc.extra+"}"), &extra); err != nil {
				t.Fatal(err)
			}
			for k, v := range extra {
				golden[k] = v
			}
			data, err := json.Marshal([]any{golden})
			if err != nil {
				t.Fatal(err)
			}
			for name, content := range map[string]string{
				"meta_physical_models.json": `[
     {"schema_name":"TS","table_name":"TBL1","column_order":"1","column_name":"CUST_NO","data_type":"VARCHAR2","length_precision":"10","is_pk":"Y","is_fk":"N"},
     {"schema_name":"TS","table_name":"TBL2","column_order":"1","column_name":"OTHER_ID","data_type":"VARCHAR2","length_precision":"10","is_pk":"Y","is_fk":"N"}
    ]`,
				"meta_logical_models.json": `[]`,
				"golden_queries.json":      string(data),
			} {
				if err := os.WriteFile(filepath.Join(dir, name), []byte(content), 0o600); err != nil {
					t.Fatal(err)
				}
			}
			var previous map[string]any
			for _, verbose := range []bool{false, true} {
				args := []string{"-data", dir}
				if verbose {
					args = append(args, "-verbose")
				}
				cmd := exec.Command(binary, args...)
				var stdout, stderr bytes.Buffer
				cmd.Stdout, cmd.Stderr = &stdout, &stderr
				err := cmd.Run()
				code := 0
				if err != nil {
					exit, ok := err.(*exec.ExitError)
					if !ok {
						t.Fatal(err)
					}
					code = exit.ExitCode()
				}
				if code != tc.exitCode {
					t.Fatalf("verbose=%t exit=%d want=%d stderr=%s", verbose, code, tc.exitCode, &stderr)
				}
				if tc.exitCode == 1 && !strings.Contains(stderr.String(), "table_selection_acc below 0.7") {
					t.Errorf("missing threshold error: %s", &stderr)
				}
				dec := json.NewDecoder(bytes.NewReader(stdout.Bytes()))
				var summary map[string]any
				if err := dec.Decode(&summary); err != nil {
					t.Fatalf("summary: %v\n%s", err, &stdout)
				}
				for key, want := range map[string]float64{"cases": 1, "table_selection_acc": tc.tableAcc, "column_recall_avg": tc.columnRecall, "metric_lookup_acc": tc.metricAcc, "join_path_acc": tc.joinAcc, "expected_sql_valid": tc.sqlValid} {
					if summary[key] != want {
						t.Errorf("%s=%v want=%v", key, summary[key], want)
					}
				}
				if len(summary) != 8 {
					t.Errorf("unexpected summary fields: %v", summary)
				}
				delete(summary, "avg_response_ms")
				if previous != nil && !reflect.DeepEqual(previous, summary) {
					t.Errorf("verbose changed summary: %v vs %v", previous, summary)
				}
				previous = summary
				if !verbose {
					var trailing any
					if err := dec.Decode(&trailing); err != io.EOF {
						t.Errorf("nonverbose has trailing output: %s", &stdout)
					}
					continue
				}
				details := strings.TrimSpace(stdout.String()[dec.InputOffset():])
				lines := strings.Split(details, "\n")
				prefix := fmt.Sprintf("[%s] table_hit=%t", tc.status, tc.tableAcc == 1)
				if !strings.HasPrefix(lines[0], prefix) || !strings.HasSuffix(lines[0], question) {
					t.Errorf("wrong case status: %s; want %s ... %s", lines[0], prefix, question)
				}
				if !strings.Contains(lines[0], fmt.Sprintf("col_recall=%.2f join=%t", tc.columnRecall, tc.joinAcc == 1)) {
					t.Errorf("wrong case metrics: %s", lines[0])
				}
				if tc.diagnostic == "" {
					if len(lines) != 1 {
						t.Errorf("unexpected diagnostics: %s", details)
					}
				} else if !strings.Contains(details, "       missing: "+tc.diagnostic) {
					t.Errorf("missing diagnostic %q: %s", tc.diagnostic, details)
				}
			}
		})
	}
}
